for (const k in H) { H[k].id = k; H[k].poly = Float64Array.from(H[k].poly); Object.freeze(H[k]); }
export const HITBOXES = Object.freeze(H);
export const HITBOX_IDS = Object.keys(H);

// The hitbox of car id (core/cars.js) or 'bot:<type>'; an unknown car id gets the first car's.
export const hitbox = id => H[id] || H[HITBOX_IDS[0]];
// Its bounding radius: no point of the polygon is farther from the centre.
export const hitRadius = id => hitbox(id).r;

// The polygon of car id at (x, z) with heading h, in world coordinates: [x0, z0, x1, z1, ...]
// into out (any array of at least poly.length numbers; no allocation then), else a new
// Float64Array. Returns it.
export function worldPoly(id, x, z, h, out) {
  const p = hitbox(id).poly, n = p.length, c = Math.cos(h), s = Math.sin(h);
  if (!out) out = new Float64Array(n);
  for (let i = 0; i < n; i += 2) { const lx = p[i], lz = p[i + 1]; out[i] = x + lx * c + lz * s; out[i + 1] = z - lx * s + lz * c; }
  return out;
}
